import {vaultExists,initializeVault,unlockVault,persistVault,lockVault,changeVaultPassword,exportEncryptedVault,importEncryptedVault} from './vault.js';
import {htmlEscape as esc,money,printInvoice,printReceipt,printStatement} from './print.js';

const $=s=>document.querySelector(s), root=$('#app');
const uid=()=>crypto.randomUUID();
const dNow=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10)};
const monthNow=()=>dNow().slice(0,7);
const datePart=v=>String(v||'').slice(0,10);
const n=x=>Number(x||0);
const e=v=>esc(v);
const fmtDate=v=>v?new Date(v+'T00:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';
const sum=(arr,fn=x=>x)=>arr.reduce((s,x)=>s+(x?.reversed?0:n(fn(x))),0);
const nameOf=(type,id)=>state?.[type]?.find(x=>x.id===id)?.name||'—';
const byId=(type,id)=>state?.[type]?.find(x=>x.id===id);
const rentInvoiceTotal=inv=>inv.reversed?0:sum(inv.items,x=>x.amount);
const invoicePaid=inv=>sum(state.payments.filter(p=>p.invoiceId===inv.id),x=>x.amount)+sum(state.allocations.filter(a=>a.invoiceId===inv.id),x=>x.amount);
const invoiceDue=inv=>inv.reversed?0:Math.max(0,rentInvoiceTotal(inv)-invoicePaid(inv));
const creditLeft=c=>c.reversed?0:Math.max(0,n(c.amount)-sum(state.allocations.filter(x=>x.creditId===c.id),x=>x.amount));
const leaseTenant=inv=>byId('leases',inv.leaseId)?.tenantId;
const unitTitle=id=>{const u=byId('units',id);return u?`${nameOf('properties',u.propertyId)} / ${u.name}`:'—'};
const leaseTitle=id=>{const l=byId('leases',id);return l?`${unitTitle(l.unitId)} · ${nameOf('tenants',l.tenantId)}`:'—'};
const activeLease=l=>l.status==='active'&&(!l.endDate||l.endDate>=dNow());
const opts=(xs,title='name')=>xs.map(x=>({value:x.id,label:String(typeof title==='function'?title(x):x[title])}));
const accountOpts=()=>opts(state.accounts.filter(a=>!a.archived));
const propertyOpts=()=>opts(state.properties.filter(x=>!x.archived));
const unitOpts=()=>opts(state.units.filter(x=>!x.archived),x=>unitTitle(x.id));
const tenantOpts=()=>opts(state.tenants.filter(x=>!x.archived));
const leaseOpts=()=>opts(state.leases,x=>leaseTitle(x.id));
const invoiceOpts=()=>opts(state.invoices,x=>`${x.no} · ${money(invoiceDue(x))} due`);
let state=null,page='dashboard',search='',modal=null,menuOpen=false,queue=Promise.resolve(),busy=false,reportAccount='all';
let toastTimer;
function toast(message,error=false){const el=$('#toast');if(!el)return;el.textContent=message;el.className=error?'visible error':'visible';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',3400)}
function createEmpty(){return {
 version:1,settings:{businessName:'My Business',address:'',phone:'',email:'',footer:'Thank you for your business.',currency:'BDT'},counters:{INV:0,RCPT:0},
 properties:[],units:[],tenants:[],leases:[],invoices:[],payments:[],accounts:[{id:uid(),name:'Cash',kind:'cash',opening:0,archived:false},{id:uid(),name:'Bank Account',kind:'bank',opening:0,archived:false}],
 deposits:[],advances:[],allocations:[],expenses:[],investments:[],returns:[],loans:[],loanPayments:[],transfers:[],maintenance:[],documents:[],audit:[]
};}
function migrate(data){const empty=createEmpty();for(const key of Object.keys(empty))if(data[key]===undefined)data[key]=empty[key];return data;}
function log(data,action,entity,label){data.audit.push({id:uid(),at:new Date().toISOString(),action,entity,label});}
function sequence(data,key){data.counters[key]=(data.counters[key]||0)+1;return `${key}-${new Date().getFullYear()}-${String(data.counters[key]).padStart(5,'0')}`;}
async function mutate(description,operation){queue=queue.catch(()=>{}).then(async()=>{busy=true;const draft=structuredClone(state);operation(draft);await persistVault(draft);state=draft;busy=false;render();toast(description);return true;}).catch(err=>{busy=false;toast(err.message||'Unable to save records',true);console.error(err);return false;});return queue;}
function downloadFile(name,content,mime='application/json'){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
function csvExport(records,filename){if(!records.length){toast('No records to export',true);return;}const keys=[...new Set(records.flatMap(r=>Object.keys(r)))];const rows=[keys.map(csvCell).join(','),...records.map(r=>keys.map(k=>csvCell(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])).join(','))];downloadFile(filename,'\ufeff'+rows.join('\r\n'),'text/csv;charset=utf-8')}
function moneyBadge(amount){return `<span class="number">${money(amount)}</span>`}
const iconPaths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',properties:'M3 21V5l9-3 9 3v16 M9 21V9h6v12 M3 11h6 M15 11h6',units:'M4 21V3h16v18 M9 7h1 M14 7h1 M9 12h1 M14 12h1 M9 21v-5h6v5',tenants:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',leases:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h8',billing:'M4 2h16v20l-4-3-4 3-4-3-4 3z M8 8h8 M8 12h8',payments:'M3 7h18v11H3z M3 10h18 M7 15h3',deposits:'M12 2v20 M5 7h11a4 4 0 0 1 0 8H5 M8 2v5 M8 15v7',advances:'M12 5v14 M5 12h14 M4 4h16v16H4z',expenses:'M2 12h20 M12 2l10 10-10 10',investments:'M3 17l6-6 4 4 8-8 M15 7h6v6',returns:'M3 17l6-6 4 4 8-8 M15 7h6v6',loans:'M12 2v20 M18 7a5 5 0 0 0-10 0c0 6 10 4 10 10a5 5 0 0 1-10 0',accounts:'M3 9l9-6 9 6 M4 10h16 M6 11v8 M10 11v8 M14 11v8 M18 11v8 M3 21h18',transfers:'M7 7h14l-4-4 M21 7l-4 4 M17 17H3l4-4 M3 17l4 4',maintenance:'M14 7l3 3-8 8-3-3z M16 5l3-2 3 3-2 3',documents:'M4 3h12l4 4v14H4z M16 3v5h4 M8 13h8 M8 17h8',reports:'M4 19V5 M4 19h17 M8 16v-5 M13 16V7 M18 16V3',audit:'M12 6v6l4 2 M22 12a10 10 0 1 1-3-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M19 13v-2 M5 13v-2 M13 5h-2 M13 19h-2',backups:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4'};
const ico=(id,size=18)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${iconPaths[id]||iconPaths.properties}"/></svg>`;
const NAV=[['OVERVIEW',[['dashboard','Dashboard'],['reports','Reports']]],['PROPERTY MANAGEMENT',[['properties','Properties'],['units','Units & Spaces'],['tenants','Tenants'],['leases','Leases'],['maintenance','Maintenance']]],['BILLING & FINANCE',[['billing','Rent & Invoices'],['payments','Payments & Receipts'],['deposits','Security Deposits'],['advances','Tenant Advances'],['expenses','Expenses'],['accounts','Bank & Cash'],['transfers','Transfers']]],['INVESTMENT',[['investments','Investments'],['returns','Investment Returns'],['loans','Loans & Repayments']]],['DATA & SYSTEM',[['documents','Documents'],['audit','Activity History'],['backups','Backup & Restore'],['settings','Business Settings']]]];
const pageNames=Object.fromEntries(NAV.flatMap(g=>g[1]));
function status(text,mode='muted'){return `<span class="status ${mode}">${e(text)}</span>`}
function statCard(title,value,sub,iconName,variant=''){return `<div class="stat-card"><div class="stat-head"><span>${e(title)}</span><div class="stat-icon ${variant}">${ico(iconName,19)}</div></div><strong>${value}</strong><small>${e(sub)}</small></div>`}
function renderShell(content){root.innerHTML=`<div class="app-shell"><div class="scrim ${menuOpen?'show':''}" data-action="menu"></div><aside class="sidebar ${menuOpen?'open':''}"><div class="brand"><div class="brand-symbol">P<span></span></div><div><strong>PropertyOS</strong><small>PRIVATE BUSINESS ERP</small></div></div><div class="side-workspace"><div class="workspace-icon">${e((state.settings.businessName||'B').slice(0,1))}</div><div><div class="muted-small">WORKSPACE</div><strong>${e(state.settings.businessName)}</strong></div><span class="workspace-lock">◉</span></div><nav>${NAV.map(([title,links])=>`<div class="nav-group"><div class="nav-label">${e(title)}</div>${links.map(([id,label])=>`<button class="nav-link ${page===id?'selected':''}" data-page="${id}">${ico(id,18)}<span>${e(label)}</span></button>`).join('')}</div>`).join('')}</nav><div class="side-bottom"><div class="private-marker"><span class="online-dot"></span> Encrypted local vault</div><button class="lock-button" data-action="lock">${ico('settings',16)} Lock workspace</button></div></aside><main class="main"><header class="topbar"><div class="top-left"><button class="mobile-menu icon-btn" data-action="menu" aria-label="Open menu">☰</button><div><div class="breadcrumb">Workspace <span>/</span> ${e(pageNames[page]||'Dashboard')}</div><h1>${e(pageNames[page]||'Dashboard')}</h1></div></div><div class="top-right"><span class="date-chip">${fmtDate(dNow())}</span><span class="top-avatar">${e((state.settings.businessName||'P').slice(0,1))}</span></div></header><section class="content">${content}</section></main></div>${modal?renderModal():''}`}
function render(){if(!state){showLock();return;}let result='';if(page==='dashboard')result=dashboard();else if(page==='reports')result=reportsPage();else if(page==='settings')result=settingsPage();else if(page==='backups')result=backupPage();else if(page==='audit')result=auditPage();else result=listPage(page);renderShell(result);}
function topIntro(text,button='',action='',secondary=''){return `<div class="page-intro"><p>${e(text)}</p><div class="page-actions">${secondary}${button?`<button class="btn primary" data-action="${action||'add'}" data-entity="${page}">＋ ${e(button)}</button>`:''}</div></div>`}
function safeChart(monthly){const max=Math.max(1,...monthly.map(m=>m.income),...monthly.map(m=>m.expense));return `<div class="chart">${monthly.map(m=>`<div class="chart-col"><div class="chart-bars"><span style="height:${Math.max(2,m.income/max*100)}%" class="bar income" title="Collected ${money(m.income)}"></span><span style="height:${Math.max(2,m.expense/max*100)}%" class="bar expense" title="Expenses ${money(m.expense)}"></span></div><small>${e(m.label)}</small></div>`).join('')}</div><div class="chart-legend"><span><i class="income"></i> Rent collected</span><span><i class="expense"></i> Expenses</span></div>`}
function dashboard(){const t=monthNow(),collected=sum(state.payments.filter(x=>x.paidOn?.startsWith(t)),x=>x.amount),expenses=sum(state.expenses.filter(x=>x.date?.startsWith(t)),x=>x.amount),outstanding=sum(state.invoices,invoiceDue),leased=new Set(state.leases.filter(activeLease).map(x=>x.unitId)),occupied=state.units.filter(x=>!x.archived&&leased.has(x.id)).length,units=state.units.filter(x=>!x.archived).length,net=collected-expenses;
const latest=state.payments.filter(x=>!x.reversed).sort((a,b)=>b.paidOn.localeCompare(a.paidOn)).slice(0,5);const overdue=state.invoices.filter(x=>!x.reversed&&x.dueDate<dNow()&&invoiceDue(x)>0).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,5);const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);const ym=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');return {label:d.toLocaleDateString('en-US',{month:'short'}),income:sum(state.payments.filter(p=>p.paidOn.startsWith(ym)),x=>x.amount),expense:sum(state.expenses.filter(x=>x.date.startsWith(ym)),x=>x.amount)};});
return `<div class="welcome"><div><span class="eyebrow">YOUR BUSINESS AT A GLANCE</span><h2>Welcome to ${e(state.settings.businessName)} <span>✦</span></h2><p>Financial clarity across every property, unit and investment.</p></div><button class="btn ghost-light" data-action="generate">${ico('billing')} Generate monthly rent</button></div><div class="stats-grid">${statCard('Rent collected this month',money(collected),`${t} payments`,'payments','mint')}${statCard('Total outstanding',money(outstanding),'All unpaid invoices','billing','amber')}${statCard('Monthly operating net',money(net),'Rent collected minus expenses','reports','blue')}${statCard('Occupancy',`${occupied} / ${units}`,`${units?Math.round(occupied/units*100):0}% occupied units`,'units','violet')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3>Cash movement</h3><p>Recent 6 months · rental receipts vs expenses</p></div>${status('Monthly','muted')}</div>${safeChart(months)}</section><section class="panel quick-panel"><div class="panel-head"><div><h3>Quick actions</h3><p>Frequently used workflows</p></div></div><div class="quick-grid"><button data-action="add" data-entity="properties">${ico('properties')}<span>Add property</span>→</button><button data-action="add" data-entity="tenants">${ico('tenants')}<span>Add tenant</span>→</button><button data-action="add" data-entity="billing">${ico('billing')}<span>Create invoice</span>→</button><button data-action="add" data-entity="payments">${ico('payments')}<span>Record payment</span>→</button><button data-action="add" data-entity="expenses">${ico('expenses')}<span>Record expense</span>→</button><button data-action="backup">${ico('backups')}<span>Export backup</span>→</button></div></section></div><div class="dashboard-grid lower"><section class="panel"><div class="panel-head"><div><h3>Outstanding invoices</h3><p>Past-due rent requiring follow-up</p></div><button class="text-button" data-page="billing">View all →</button></div>${overdue.length?`<div class="mini-list">${overdue.map(inv=>`<div><div><strong>${e(inv.no)}</strong><small>${e(leaseTitle(inv.leaseId))} · Due ${fmtDate(inv.dueDate)}</small></div><span class="negative">${money(invoiceDue(inv))}</span></div>`).join('')}</div>`:emptyMini('No overdue invoices yet')}</section><section class="panel"><div class="panel-head"><div><h3>Recent receipts</h3><p>Latest rental payments</p></div><button class="text-button" data-page="payments">View all →</button></div>${latest.length?`<div class="mini-list">${latest.map(p=>`<div><div><strong>${e(p.receiptNo)}</strong><small>${e(nameOf('accounts',p.accountId))} · ${fmtDate(p.paidOn)}</small></div><span class="positive">${money(p.amount)}</span></div>`).join('')}</div>`:emptyMini('No payments recorded yet')}</section></div>`}
const emptyMini=t=>`<div class="mini-empty">${ico('documents',24)}<p>${e(t)}</p></div>`;
const tableColumns={
 properties:[['Property',r=>`<b>${e(r.name)}</b><small>${e(r.kind||'Asset')}</small>`],['Address',r=>e(r.address)],['Units',r=>state.units.filter(u=>u.propertyId===r.id).length],['Status',r=>status(r.archived?'Archived':'Active',r.archived?'muted':'good')]],
 units:[['Unit',r=>`<b>${e(r.name)}</b><small>${e(r.type||'Rental space')}</small>`],['Property',r=>e(nameOf('properties',r.propertyId))],['Rent (default)',r=>moneyBadge(r.defaultRent)],['Occupancy',r=>status(state.leases.some(l=>l.unitId===r.id&&activeLease(l))?'Occupied':'Vacant',state.leases.some(l=>l.unitId===r.id&&activeLease(l))?'good':'warn')]],
 tenants:[['Tenant',r=>`<b>${e(r.name)}</b><small>${e(r.email)}</small>`],['Phone',r=>e(r.phone)],['Current leases',r=>state.leases.filter(l=>l.tenantId===r.id&&activeLease(l)).length],['Status',r=>status(r.archived?'Archived':'Active',r.archived?'muted':'good')]],
 leases:[['Unit / Space',r=>`<b>${e(unitTitle(r.unitId))}</b><small>${e(nameOf('tenants',r.tenantId))}</small>`],['Term',r=>`${fmtDate(r.startDate)} – ${fmtDate(r.endDate)||'Open'}`],['Monthly rent',r=>moneyBadge(r.rent)],['Status',r=>status(activeLease(r)?'Active':'Closed',activeLease(r)?'good':'muted')]],
 billing:[['Invoice',r=>`<b>${e(r.no)}</b><small>${e(r.period)} · ${e(leaseTitle(r.leaseId))}</small>`],['Due',r=>fmtDate(r.dueDate)],['Amount',r=>moneyBadge(rentInvoiceTotal(r))],['Paid',r=>moneyBadge(invoicePaid(r))],['Balance',r=>`<strong class="${invoiceDue(r)?'negative':'positive'}">${money(invoiceDue(r))}</strong>`],['Status',r=>invoiceDue(r)===0?status('Paid','good'):invoicePaid(r)>0?status('Partial','warn'):r.dueDate<dNow()?status('Overdue','danger'):status('Unpaid','muted')]],
 payments:[['Receipt',r=>`<b>${e(r.receiptNo)}</b><small>${e(byId('invoices',r.invoiceId)?.no)}</small>`],['Date',r=>fmtDate(r.paidOn)],['Method / Account',r=>`${e(r.method)}<small>${e(nameOf('accounts',r.accountId))}</small>`],['Amount',r=>`<strong class="positive">${money(r.amount)}</strong>`],['Reference',r=>e(r.reference)]],
 deposits:[['Lease / Tenant',r=>`<b>${e(leaseTitle(r.leaseId))}</b>`],['Date',r=>fmtDate(r.date)],['Type',r=>status(r.type==='received'?'Deposit received':'Deposit refunded',r.type==='received'?'good':'warn')],['Amount',r=>moneyBadge(r.amount)],['Account',r=>e(nameOf('accounts',r.accountId))]],
 advances:[['Tenant',r=>`<b>${e(nameOf('tenants',r.tenantId))}</b><small>${e(r.reference)}</small>`],['Date',r=>fmtDate(r.date)],['Received',r=>moneyBadge(r.amount)],['Available to allocate',r=>`<b class="positive">${money(creditLeft(r))}</b>`],['Account',r=>e(nameOf('accounts',r.accountId))]],
 expenses:[['Expense',r=>`<b>${e(r.name)}</b><small>${e(r.category)}</small>`],['Property',r=>e(nameOf('properties',r.propertyId))],['Date',r=>fmtDate(r.date)],['Account',r=>e(nameOf('accounts',r.accountId))],['Amount',r=>`<b class="negative">${money(r.amount)}</b>`]],
 accounts:[['Account',r=>`<b>${e(r.name)}</b><small>${e(r.kind)}</small>`],['Opening balance',r=>moneyBadge(r.opening)],['Current balance',r=>`<b>${money(accountBalance(r.id))}</b>`],['Status',r=>status(r.archived?'Archived':'Active',r.archived?'muted':'good')]],
 transfers:[['From account',r=>e(nameOf('accounts',r.fromAccountId))],['To account',r=>e(nameOf('accounts',r.toAccountId))],['Date',r=>fmtDate(r.date)],['Amount',r=>moneyBadge(r.amount)],['Notes',r=>e(r.notes)]],
 investments:[['Investment',r=>`<b>${e(r.name)}</b><small>${e(r.type)}</small>`],['Linked property',r=>e(nameOf('properties',r.propertyId))],['Invested on',r=>fmtDate(r.date)],['Capital',r=>moneyBadge(r.principal)],['Received returns',r=>`<b class="positive">${money(sum(state.returns.filter(x=>x.investmentId===r.id),x=>x.amount))}</b>`]],
 returns:[['Investment',r=>`<b>${e(nameOf('investments',r.investmentId))}</b>`],['Date',r=>fmtDate(r.date)],['Type',r=>e(r.type)],['Account',r=>e(nameOf('accounts',r.accountId))],['Amount',r=>`<b class="positive">${money(r.amount)}</b>`]],
 loans:[['Lender / Loan',r=>`<b>${e(r.name)}</b><small>${e(r.lender)}</small>`],['Started',r=>fmtDate(r.date)],['Original principal',r=>moneyBadge(r.principal)],['Principal outstanding',r=>`<b class="negative">${money(Math.max(0,n(r.principal)-sum(state.loanPayments.filter(x=>x.loanId===r.id),x=>x.principalAmount)))}</b>`],['Interest rate',r=>`${n(r.interestRate)}%`]],
 maintenance:[['Issue',r=>`<b>${e(r.name)}</b><small>${e(unitTitle(r.unitId))}</small>`],['Reported',r=>fmtDate(r.date)],['Priority',r=>status(r.priority,r.priority==='High'?'danger':r.priority==='Medium'?'warn':'muted')],['Status',r=>status(r.status,r.status==='Completed'?'good':'warn')],['Estimated cost',r=>moneyBadge(r.estimatedCost)]],
 documents:[['File',r=>`<b>${e(r.name)}</b><small>${e(r.fileName)}</small>`],['Linked to',r=>`${e(r.relatedType||'General')} · ${e(r.relatedId||'')}`],['Uploaded',r=>fmtDate(r.date)],['Size',r=>`${Math.round(n(r.bytes)/1024)} KB`]]
};
const collectionKey={billing:'invoices',returns:'returns',...Object.fromEntries(Object.keys(tableColumns).map(k=>[k,k]))};
const descriptions={properties:'Manage residential, commercial and land assets in one portfolio.',units:'Track each flat, shop, parking space or rental unit.',tenants:'Manage tenant contacts and complete tenancy history.',leases:'Link each tenant to a unit, agreed rent and lease dates.',billing:'Generate monthly rent invoices and monitor unpaid balances.',payments:'Record collections and print professional money receipts.',deposits:'Track refundable deposits separately from rental income.',advances:'Record unallocated tenant money and apply it to future invoices.',expenses:'Track operating costs, repairs and property-related spending.',accounts:'Monitor all cash and bank movements with traceable statements.',transfers:'Move funds between your registered financial accounts.',investments:'Record invested capital and monitor investment returns.',returns:'Record income distributed by your investments.',loans:'Track loans, interest charges and repayments.',maintenance:'Keep a record of repairs, issues and their progress.',documents:'Keep small scanned agreements or supporting files inside the encrypted vault.'};
const addNames={properties:'Add property',units:'Add unit',tenants:'Add tenant',leases:'Create lease',billing:'Create invoice',payments:'Record payment',deposits:'Record deposit',advances:'Record advance',expenses:'Add expense',accounts:'Add account',transfers:'New transfer',investments:'Add investment',returns:'Record return',loans:'Add loan',maintenance:'New maintenance issue',documents:'Upload document'};
const editable=new Set(['properties','units','tenants','leases','accounts','investments','maintenance']);
const archivable=new Set(['properties','units','tenants','accounts']);
const reversible=new Set(['billing','payments','deposits','advances','allocations','expenses','transfers','investments','returns','loans','loanPayments']);
function listPage(which){const key=collectionKey[which];let rows=[...(state[key]||[])];if(search)rows=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));rows.sort((a,b)=>(b.date||b.createdAt||b.issued||b.paidOn||'').localeCompare(a.date||a.createdAt||a.issued||a.paidOn||''));const cols=tableColumns[which]||[];let auxiliary='';
 if(which==='billing')auxiliary=`<div class="inline-toolbar"><label>Billing month <input id="bill-month" type="month" value="${monthNow()}"></label><button class="btn soft" data-action="generate">${ico('billing',15)} Generate all rent bills</button><button class="btn soft" data-action="add" data-entity="payments">＋ Receive payment</button></div>`;
 if(which==='advances')auxiliary=`<div class="inline-toolbar"><button class="btn soft" data-action="add" data-entity="allocations">＋ Allocate advance to invoice</button><span class="muted-small">Applying credits does not create another bank transaction.</span></div>`;
 if(which==='loans')auxiliary=`<div class="inline-toolbar"><button class="btn soft" data-action="add" data-entity="loanPayments">＋ Record loan repayment</button><span class="muted-small">Loan proceeds are not counted as rental income.</span></div><div class="panel embedded"><h3>Loan repayment history</h3>${smallRecords('loanPayments',state.loanPayments,r=>`${e(nameOf('loans',r.loanId))} · ${fmtDate(r.date)}`,r=>money(n(r.principalAmount)+n(r.interestAmount)))}</div>`;
 if(which==='deposits')auxiliary=`<p class="tip">Security deposits are liabilities, not rental income. Received deposits increase cash; refunds decrease cash.</p>`;
 if(which==='accounts')auxiliary=`<div class="inline-toolbar"><button class="btn soft" data-page="reports">${ico('reports',15)} View full cash & bank ledger</button></div>`;
 if(which==='documents')auxiliary=`<p class="tip">Each uploaded file is encrypted, included in backups, and stored only in this browser. Maximum 3 MB per file.</p>`;
const summary=which==='billing'?`<div class="inline-summary">Total receivable: <strong>${money(sum(state.invoices,rentInvoiceTotal))}</strong> &nbsp; · &nbsp; Outstanding: <strong class="negative">${money(sum(state.invoices,invoiceDue))}</strong></div>`:which==='accounts'?`<div class="inline-summary">Combined balance: <strong>${money(sum(state.accounts,x=>accountBalance(x.id)))}</strong></div>`:'';
return `${topIntro(descriptions[which]||'',addNames[which]||'Add','add',`<button class="btn soft" data-action="csv" data-entity="${key}">${ico('documents',15)} Export CSV</button>`)}${auxiliary}${summary}<section class="panel table-panel"><div class="panel-head"><div><h3>${e(pageNames[which])}</h3><p>${rows.length} ${rows.length===1?'record':'records'}${search?' matching your search':''}</p></div><div class="table-tools"><input data-search type="search" placeholder="Search records..." value="${e(search)}" aria-label="Search records"/></div></div><div class="table-scroll"><table class="data-table"><thead><tr>${cols.map(c=>`<th>${e(c[0])}</th>`).join('')}<th class="actions-head">Actions</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${cols.map(c=>`<td>${c[1](r)}${r.reversed?'<small class="negative">REVERSED</small>':''}</td>`).join('')}<td><div class="row-actions">${which==='billing'&&!r.reversed?`<button title="Print invoice" data-action="printInvoice" data-id="${r.id}">Print</button>`:''}${which==='payments'&&!r.reversed?`<button title="Print money receipt" data-action="printReceipt" data-id="${r.id}">Receipt</button>`:''}${which==='accounts'?`<button data-action="statement" data-id="${r.id}">Statement</button>`:''}${which==='documents'?`<button data-action="downloadDocument" data-id="${r.id}">Open</button>`:''}${editable.has(which)?`<button data-action="edit" data-entity="${which}" data-id="${r.id}">Edit</button>`:''}${archivable.has(which)?`<button data-action="archive" data-entity="${which}" data-id="${r.id}">${r.archived?'Restore':'Archive'}</button>`:''}${reversible.has(which)&&!r.reversed?`<button data-action="reverse" data-entity="${which}" data-id="${r.id}">Reverse</button>`:''}</div></td></tr>`).join(''):`<tr><td colspan="${cols.length+1}" class="empty-row">No ${e(pageNames[which].toLowerCase())} found. Use the add button to get started.</td></tr>`}</tbody></table></div></section>`;}
function smallRecords(key,rows,first,second){return rows.length?`<div class="mini-list">${[...rows].reverse().slice(0,8).map(r=>`<div><div><strong>${first(r)}</strong></div><b>${second(r)}</b></div>`).join('')}</div>`:emptyMini('No records yet')}
function entries(){const out=[];function push(collection,date,accountId,amount,description,sort){if(accountId)out.push({collection,date,accountId,amount:n(amount),description,sort});}
state.payments.filter(x=>!x.reversed).forEach(x=>push('Rent',x.paidOn,x.accountId,x.amount,`Rent receipt ${x.receiptNo}`,x.id));
state.deposits.filter(x=>!x.reversed).forEach(x=>push('Deposit',x.date,x.accountId,x.type==='received'?x.amount:-x.amount,`Security deposit ${x.type} · ${leaseTitle(x.leaseId)}`,x.id));
state.advances.filter(x=>!x.reversed).forEach(x=>push('Advance',x.date,x.accountId,x.amount,`Tenant advance · ${nameOf('tenants',x.tenantId)}`,x.id));
state.expenses.filter(x=>!x.reversed).forEach(x=>push('Expense',x.date,x.accountId,-x.amount,`Expense · ${x.name}`,x.id));
state.investments.filter(x=>!x.reversed).forEach(x=>push('Investment',x.date,x.accountId,-x.principal,`Invested capital · ${x.name}`,x.id));
state.returns.filter(x=>!x.reversed).forEach(x=>push('Return',x.date,x.accountId,x.amount,`Investment income · ${nameOf('investments',x.investmentId)}`,x.id));
state.loans.filter(x=>!x.reversed).forEach(x=>push('Loan',x.date,x.accountId,x.principal,`Loan proceeds · ${x.name}`,x.id));
state.loanPayments.filter(x=>!x.reversed).forEach(x=>push('Loan repayment',x.date,x.accountId,-n(x.principalAmount)-n(x.interestAmount),`Loan payment · ${nameOf('loans',x.loanId)}`,x.id));
state.transfers.filter(x=>!x.reversed).forEach(x=>{push('Transfer',x.date,x.fromAccountId,-x.amount,`Transfer to ${nameOf('accounts',x.toAccountId)}`,x.id+'a');push('Transfer',x.date,x.toAccountId,x.amount,`Transfer from ${nameOf('accounts',x.fromAccountId)}`,x.id+'b');});
return out.sort((a,b)=>a.date.localeCompare(b.date)||a.sort.localeCompare(b.sort));}
function accountBalance(id){const acc=byId('accounts',id);if(!acc)return 0;return n(acc.opening)+sum(entries().filter(x=>x.accountId===id),x=>x.amount);}
function reportsPage(){const ledger=entries().filter(x=>reportAccount==='all'||x.accountId===reportAccount);const chronological=[...ledger].reverse().slice(0,150);const credits=sum(ledger.filter(x=>x.amount>0),x=>x.amount),debits=-sum(ledger.filter(x=>x.amount<0),x=>x.amount),profit=sum(state.payments,x=>x.amount)-sum(state.expenses,x=>x.amount);const accOptions=[{value:'all',label:'All accounts'},...opts(state.accounts)];
return `${topIntro('Bank-statement-style activity and business-wide financial reports.','','',`<button class="btn soft" data-action="ledgerCSV">Export ledger CSV</button>`)}<div class="stats-grid three">${statCard('All account balances',money(sum(state.accounts,x=>accountBalance(x.id))),'Available cash and bank funds','accounts','mint')}${statCard('Recorded rent profit',money(profit),'Total rent paid less operational expenses','returns','blue')}${statCard('Outstanding rent',money(sum(state.invoices,invoiceDue)),'Still receivable from tenants','billing','amber')}</div><section class="panel table-panel"><div class="panel-head"><div><h3>Cash & bank ledger</h3><p>Debit = money out · Credit = money in. Up to 150 latest rows shown.</p></div><select id="report-account">${accOptions.map(o=>`<option value="${e(o.value)}" ${reportAccount===o.value?'selected':''}>${e(o.label)}</option>`).join('')}</select></div><div class="summary-row"><div><small>Movements in</small><b class="positive">${money(credits)}</b></div><div><small>Movements out</small><b class="negative">${money(debits)}</b></div><div><small>Total transactions</small><b>${ledger.length}</b></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Account</th><th>Category</th><th>Details</th><th>Debit</th><th>Credit</th></tr></thead><tbody>${chronological.length?chronological.map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${e(nameOf('accounts',x.accountId))}</td><td>${e(x.collection)}</td><td>${e(x.description)}</td><td class="negative">${x.amount<0?money(-x.amount):'—'}</td><td class="positive">${x.amount>0?money(x.amount):'—'}</td></tr>`).join(''):`<tr><td colspan="6" class="empty-row">No activity yet</td></tr>`}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h3>Account statements</h3><p>Downloadable print/PDF account records including running balances.</p></div></div><div class="account-cards">${state.accounts.map(a=>`<button class="account-card" data-action="statement" data-id="${a.id}"><span>${ico('accounts',20)} ${e(a.name)}</span><strong>${money(accountBalance(a.id))}</strong><small>View / print statement ↗</small></button>`).join('')}</div></section>${advancedReports()}`;}
function auditPage(){return `${topIntro('A permanent local activity trail records changes made within this vault.','','',`<button class="btn soft" data-action="csv" data-entity="audit">Export audit CSV</button>`)}<section class="panel table-panel"><div class="panel-head"><h3>Record history</h3><p>${state.audit.length} logged actions</p></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date / Time</th><th>Action</th><th>Record type</th><th>Details</th></tr></thead><tbody>${[...state.audit].reverse().map(x=>`<tr><td>${e(new Date(x.at).toLocaleString('en-GB'))}</td><td>${status(x.action,'muted')}</td><td>${e(x.entity)}</td><td>${e(x.label)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty-row">No history yet</td></tr>'}</tbody></table></div></section>`;}
function settingsPage(){const s=state.settings;return `${topIntro('Set the details shown on professional invoices, receipts and printed statements.')}<div class="settings-grid"><section class="panel"><h3>Business identity</h3><form id="settings-form" class="field-grid"><label class="span-2">Business / company name<input name="businessName" required value="${e(s.businessName)}"></label><label class="span-2">Business address<textarea name="address" rows="2">${e(s.address)}</textarea></label><label>Phone<input name="phone" value="${e(s.phone)}"></label><label>Email<input type="email" name="email" value="${e(s.email)}"></label><label class="span-2">Invoice & receipt footer<textarea name="footer" rows="2">${e(s.footer)}</textarea></label><div class="span-2"><button class="btn primary" type="submit">Save business details</button></div></form></section><section class="panel"><h3>Vault security</h3><p class="muted">Change the password that encrypts all your business records. If you forget it and have no usable backup, the data cannot be recovered.</p><form id="password-form" class="field-grid one"><label>Current password<input type="password" name="current" autocomplete="current-password" required></label><label>New password (at least 10 characters)<input type="password" name="next" autocomplete="new-password" minlength="10" required></label><label>Confirm new password<input type="password" name="confirm" autocomplete="new-password" minlength="10" required></label><button class="btn soft">Change password</button></form><hr><p class="muted">Your data never leaves this browser unless you export it. Nothing is saved to GitHub or Vercel.</p><button class="btn soft" data-action="lock">Lock app now</button></section></div>`;}
function backupPage(){return `${topIntro('Own your data. Download encrypted backups and CSV files regularly.')}<div class="backup-grid"><section class="panel backup-box"><div class="big-symbol">${ico('backups',28)}</div><h3>Encrypted complete backup</h3><p>Includes property data, every transaction, settings, audit history and uploaded documents. Protected by your vault password.</p><button class="btn primary" data-action="backup">Download encrypted backup</button><small>Recommended after every major update.</small></section><section class="panel backup-box"><div class="big-symbol amber">${ico('documents',28)}</div><h3>Restore encrypted backup</h3><p>Restore a previously exported PropertyOS backup. This <b>replaces every current record</b> on this device.</p><label class="btn soft upload-btn">Choose backup file<input type="file" id="restore-file" accept=".json,application/json" hidden></label><small>You'll be asked for the backup password.</small></section><section class="panel backup-box"><div class="big-symbol blue">${ico('reports',28)}</div><h3>Export all data as CSV</h3><p>Downloads a ZIP-free series of CSV tables from every module. These files are unencrypted; store them securely.</p><button class="btn soft" data-action="csvAll">Export all CSV tables</button><small>Useful for Excel and independent data analysis.</small></section><section class="panel backup-box"><div class="big-symbol">${ico('audit',28)}</div><h3>Data storage & privacy</h3><p>Records are encrypted with AES-GCM and stored in your browser's IndexedDB. This is a local-first PWA, without servers or subscriptions.</p><button class="btn soft" data-page="audit">View change history</button><small>Clearing browser site data can delete the working vault. Back up regularly.</small></section></div>`;}
