// Supplementary reports use the same financial records as the cash ledger.
function advancedReports(){
 const linkedProperty=inv=>{const lease=byId('leases',inv.leaseId),unit=byId('units',lease?.unitId);return unit?.propertyId||''};
 const props=state.properties.map(p=>{const invoices=state.invoices.filter(inv=>!inv.reversed&&linkedProperty(inv)===p.id);return {property:p.name,units:state.units.filter(x=>x.propertyId===p.id).length,invoiced:sum(invoices,rentInvoiceTotal),allocated:sum(invoices,invoicePaid),expenses:sum(state.expenses.filter(x=>x.propertyId===p.id),x=>x.amount)};});
 const overdue=state.invoices.filter(inv=>!inv.reversed&&inv.dueDate<dNow()&&invoiceDue(inv)>0);
 const aged={a:0,b:0,c:0,d:0};for(const inv of overdue){const days=Math.floor((new Date(dNow()+'T00:00:00')-new Date(inv.dueDate+'T00:00:00'))/86400000);const key=days<=30?'a':days<=60?'b':days<=90?'c':'d';aged[key]+=invoiceDue(inv);}
 const capital=sum(state.investments,x=>x.principal),returns=sum(state.returns,x=>x.amount),loans=sum(state.loans,x=>x.principal)-sum(state.loanPayments,x=>x.principalAmount),security=sum(state.deposits.filter(x=>x.type==='received'),x=>x.amount)-sum(state.deposits.filter(x=>x.type==='refunded'),x=>x.amount);
 return `<div class="dashboard-grid lower report-bottom"><section class="panel"><div class="panel-head"><div><h3>Property performance</h3><p>Billed and allocated rental income by property</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Property</th><th>Units</th><th>Billed</th><th>Received / applied</th><th>Expenses</th></tr></thead><tbody>${props.map(p=>`<tr><td><b>${e(p.property)}</b></td><td>${p.units}</td><td>${money(p.invoiced)}</td><td class="positive">${money(p.allocated)}</td><td class="negative">${money(p.expenses)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-row">No properties yet</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h3>Overdue rent ageing</h3><p>Unpaid balances by days past due</p></div></div><div class="age-grid">${[['0–30 days',aged.a],['31–60 days',aged.b],['61–90 days',aged.c],['90+ days',aged.d]].map(([title,value])=>`<div><small>${e(title)}</small><strong>${money(value)}</strong></div>`).join('')}</div><h3 style="margin-top:25px">Financial position indicators</h3><div class="mini-list"><div><div><strong>Capital invested</strong></div><b>${money(capital)}</b></div><div><div><strong>Investment returns received</strong></div><b class="positive">${money(returns)}</b></div><div><div><strong>Simple return / capital</strong></div><b>${capital?(returns/capital*100).toFixed(2):'0.00'}%</b></div><div><div><strong>Loan principal outstanding</strong></div><b class="negative">${money(Math.max(0,loans))}</b></div><div><div><strong>Refundable deposits held</strong></div><b>${money(Math.max(0,security))}</b></div></div></section></div>`;
}
